def make_task(
    id: int = 1,
    title: str = "Test task",
    status: TaskStatus = TaskStatus.PENDING,
    priority: TaskPriority = TaskPriority.MEDIUM,
    due_at: datetime | None = None,
    completed_at: datetime | None = None,
    created_at: datetime = FIXED_NOW,
    tags: list[Tag] | None = None,
) -> Task:
    return Task(
        id=id,
        title=title,
        status=status,
        priority=priority,
        due_at=due_at,
        completed_at=completed_at,
        created_at=created_at,
        tags=tags or [],
    )

"""Tests for tasks_api.models — Task, Tag, TaskStatus, TaskPriority."""

from __future__ import annotations

from datetime import datetime, timezone

import pytest

from tasks_api.models import Tag, Task, TaskPriority, TaskStatus


# ── Tag ──────────────────────────────────────────────────────────────────

class TestTag:
    def test_normalizes_to_lowercase_stripped(self):
        assert Tag("  Hello  ").name == "hello"

    def test_allows_hyphens_and_underscores(self):
        assert Tag("my-tag_1").name == "my-tag_1"

    @pytest.mark.parametrize("bad", ["", "   ", None])
    def test_rejects_empty_or_none(self, bad):
        if bad is None:
            with pytest.raises(TypeError):
                Tag(bad)
        else:
            with pytest.raises(ValueError, match="must not be empty"):
                Tag(bad)

    def test_rejects_too_long(self):
        with pytest.raises(ValueError, match="32 characters"):
            Tag("a" * 33)

    def test_rejects_illegal_characters(self):
        with pytest.raises(ValueError, match="illegal character"):
            Tag("hello world")

    def test_non_string_raises_type_error(self):
        with pytest.raises(TypeError):
            Tag(123)


