# ── Task.is_overdue ──────────────────────────────────────────────────────

class TestTaskIsOverdue:
    def test_no_due_date(self):
        t = Task(id=1, title="x")
        assert t.is_overdue(datetime.now(timezone.utc)) is False

    def test_done_task_not_overdue(self):
        past = datetime(2020, 1, 1, tzinfo=timezone.utc)
        t = Task(id=1, title="x", status=TaskStatus.DONE, due_at=past)
        assert t.is_overdue(datetime(2025, 1, 1, tzinfo=timezone.utc)) is False

    def test_pending_past_due(self):
        past = datetime(2020, 1, 1, tzinfo=timezone.utc)
        t = Task(id=1, title="x", due_at=past)
        assert t.is_overdue(datetime(2025, 1, 1, tzinfo=timezone.utc)) is True

    def test_pending_future_due(self):
        future = datetime(2030, 1, 1, tzinfo=timezone.utc)
        t = Task(id=1, title="x", due_at=future)
        assert t.is_overdue(datetime(2025, 1, 1, tzinfo=timezone.utc)) is False


